    triggerInput(input, 'ct');
    await flushDebounce();

    const pathEl = findFirst(container, (el) => el.classList.has('rp-stp-result-path'));
    expect(pathEl).not.toBeNull();
    expect(pathEl?.textContent).toBe('abdomen/ct/ct-routine.md');
  });
});

